function textOf(data){
  const c=[data?.content?.parts?.[0]?.text,data?.candidates?.[0]?.content?.parts?.[0]?.text,
    Array.isArray(data?.content)?data.content.find(x=>x?.type==='text')?.text:undefined,
    data?.text,typeof data?.content==='string'?data.content:undefined];
  return c.find(x=>typeof x==='string'&&x.trim())||'';
}
function jsonOf(text){
  let s=String(text||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
  const a=s.indexOf('{'),b=s.lastIndexOf('}');
  if(a>=0&&b>a)s=s.slice(a,b+1);
  return JSON.parse(s);
}

const context=$('Prepare Duplicate Context').item.json;
try {
  const d=jsonOf(textOf($json));
  return {json:{...context,isDuplicate:context.exactSourceMatch===true||d?.isDuplicate===true,matchedTitle:String(d?.matchedTitle||''),duplicateReason:String(d?.reason||'')}};
} catch (e) {
  return {json:{...context,isDuplicate:true,matchedTitle:'',duplicateReason:'Duplicate check could not be parsed; skipped safely.',duplicateParserError:e.message}};
}

