function restoreProperNouns(title, reference){
  const prose=' '+String(reference||'').split('\n').filter(l=>!/^\s*#/.test(l)).join(' ').replace(/\s+/g,' ')+' ';
  const count=(re)=>(prose.match(re)||[]).length;
  const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  let first=true;
  return String(title).split(/(\s+)/).map(t=>{
    if(!/\S/.test(t)) return t;
    if(first){ first=false; return t; }
    const m=t.match(/^([^A-Za-z]*)([a-z][a-z'’\-]+)([^A-Za-z]*)$/);
    if(!m || m[2].length<3 || FUNCTION_WORDS.has(m[2])) return t;
    const capped=m[2][0].toUpperCase()+m[2].slice(1);
    const cappedMid=count(new RegExp('[a-z0-9,;’\'*_]\\s'+esc(capped)+'(?=[\\s,.;:!?)"”\'’*_])','g'));
