// Nuvellum house-style gate for generated editorial SVGs. Returns a list of problems; empty = premium enough.
// Rejects the generic AI look: neon cyan/magenta, glow on saturated colour, dark full-bleed canvases,
// particle swarms, fake UI panels, thin low-detail drawings and palettes outside the house range.
function styleProblems(svg){
  const problems=[];
  const toHsl=(r,g,b)=>{r/=255;g/=255;b/=255;const mx=Math.max(r,g,b),mn=Math.min(r,g,b),l=(mx+mn)/2;let h=0,s=0;if(mx!==mn){const d=mx-mn;s=l>0.5?d/(2-mx-mn):d/(mx+mn);h=mx===r?((g-b)/d+(g<b?6:0)):mx===g?((b-r)/d+2):((r-g)/d+4);h*=60;}return{h,s,l};};
  const hex=x=>{if(x.length===3)x=x.split('').map(c=>c+c).join('');return toHsl(parseInt(x.slice(0,2),16),parseInt(x.slice(2,4),16),parseInt(x.slice(4,6),16));};
  const colors=[];
  for(const m of svg.matchAll(/#([0-9a-f]{6}|[0-9a-f]{3})\b/gi))colors.push(hex(m[1]));
  for(const m of svg.matchAll(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/gi))colors.push(toHsl(+m[1],+m[2],+m[3]));
  for(const m of svg.matchAll(/hsla?\(\s*([\d.]+)\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%/gi))colors.push({h:+m[1],s:+m[2]/100,l:+m[3]/100});
  const saturated=colors.filter(c=>c.s>=0.5&&c.l>=0.3&&c.l<=0.8);
  if(saturated.some(c=>(c.h>=160&&c.h<=205)||(c.h>=265&&c.h<=330))) problems.push('neon cyan/magenta/purple colour');
  const bright=colors.filter(c=>c.s>=0.55&&c.l>=0.45&&c.l<=0.85);
  if(/<\s*feGaussianBlur\b/i.test(svg)&&bright.length) problems.push('glow blur on saturated colour');
  const bg=svg.match(/<rect\b[^>]*\bwidth\s*=\s*["'](?:100%|1200)["'][^>]*>/i);
  const fill=bg?((bg[0].match(/fill\s*=\s*["']([^"']+)["']/i)||[])[1]||''):'';
  let canvasL=null;
  const hexFill=fill.match(/^#([0-9a-f]{6}|[0-9a-f]{3})$/i);
  if(hexFill) canvasL=hex(hexFill[1]).l;
  const ref=fill.match(/url\(#([\w-]+)\)/);
  if(ref){
    const grad=[...svg.matchAll(/<(linear|radial)Gradient\b[^>]*\bid\s*=\s*["']([\w-]+)["'][\s\S]*?<\/\1Gradient>/gi)].find(m=>m[2]===ref[1]);
    const stops=grad?[...grad[0].matchAll(/stop-color\s*=\s*["']#([0-9a-f]{6}|[0-9a-f]{3})["']/gi)].map(m=>hex(m[1]).l):[];
    if(stops.length) canvasL=stops.reduce((a,b)=>a+b,0)/stops.length;
  }
  if(canvasL!==null&&canvasL<0.25) problems.push('dark full-bleed canvas (house style is paper-toned)');
  const smallCircles=[...svg.matchAll(/<circle\b[^>]*\br\s*=\s*["']([\d.]+)["']/gi)].filter(m=>+m[1]<=6).length;
  if(smallCircles>18) problems.push('particle swarm ('+smallCircles+' tiny circles)');
  const panels=[...svg.matchAll(/<rect\b[^>]*\brx\s*=\s*["']([\d.]+)["']/gi)].filter(m=>+m[1]>=6&&+m[1]<=40).length;
  if(panels>=5) problems.push('UI-panel rounded rectangles ('+panels+')');
  const drawn=(svg.match(/<(path|rect|circle|ellipse|polygon|polyline|line)\b/gi)||[]).length;
  if(drawn<14) problems.push('low-detail drawing ('+drawn+' elements)');
  const hueBuckets=new Set(saturated.map(c=>Math.round(c.h/30)%12));
  if(hueBuckets.size>4) problems.push('palette sprawl ('+hueBuckets.size+' saturated hues)');
  const house=colors.filter(c=>c.s<0.28||((c.h>=330||c.h<=18)&&c.l<=0.5)||(c.h>=18&&c.h<=55&&c.s<0.45));
  if(colors.length>=4&&house.length/colors.length<0.6) problems.push('palette outside the Nuvellum house range');
  return problems;
}

function removeFrontmatter(markdown,key){
  const lines=String(markdown||'').split('\n');
  if(lines[0]!=='---') return markdown;
  const end=lines.indexOf('---',1);
  if(end<0) return markdown;
  return lines.filter((line,i)=>!(i>0&&i<end&&line.startsWith(key+':'))).join('\n');
}

// Image policy: real images first. The repository's visual-acquisition job runs on every incoming branch and
// adds an openly licensed photo when one clears its threshold. A generated SVG is used only if it passes both
// the safety and style gates. Otherwise the story carries no image at all and the site sets it text-led:
// generic section art must never stand in for the story.
function textLed(article){
  let markdown=removeFrontmatter(article.markdown,'image');
  markdown=removeFrontmatter(markdown,'imageAlt');
  return {...article,markdown,image:'',imageAlt:'',aiImageReady:false,imageGenerationMode:'text-led'};
}

const article=currentArticle();
let result=textLed(article);

const ALLOWED=new Set(['svg','g','defs','style','path','rect','circle','ellipse','line','polyline','polygon','lineargradient','radialgradient','stop','clippath','mask','pattern','filter','title','desc',
  'fegaussianblur','feoffset','feblend','fecolormatrix','femerge','femergenode','feflood','fecomposite','feturbulence','fedisplacementmap','fedropshadow','fecomponenttransfer','fefunca','fefuncr','fefuncg','fefuncb','femorphology']);
// Same patterns the repository validator blocks in content, plus SVG-specific vectors.
const FORBIDDEN=[/<\s*script\b/i,/<\s*iframe\b/i,/<\s*object\b/i,/<\s*embed\b/i,/<\s*form\b/i,/<\s*foreignObject\b/i,/<\s*image\b/i,/<\s*use\b/i,/<\s*a\b/i,/expression\s*\(/i,/behavior\s*:/i,/<\s*animate/i,/<\s*set\b/i,
  /javascript\s*:/i,/\bon\w+\s*=/i,/\b(?:xlink:)?href\s*=/i,/data\s*:/i,/@import/i,/url\(\s*["']?\s*(?!#)/i,/<!ENTITY/i,/<!DOCTYPE/i];

try{
  let svg=textOf($json).trim()
    .replace(/^```(?:svg|xml)?\s*/i,'')
    .replace(/\s*```$/,'')
    .trim();

  const start=svg.indexOf('<svg');
  const end=svg.lastIndexOf('</svg>');
  if(start<0||end<start) throw new Error('No complete SVG returned');
  svg=svg.slice(start,end+6);

  if(svg.length<350) throw new Error('SVG too small');
  if(svg.length>120000) throw new Error('SVG too large');

  // Remove unsafe/unsupported content rather than discarding an otherwise usable illustration.
  svg=svg
    .replace(/<\?xml[\s\S]*?\?>/gi,'')
    .replace(/<!DOCTYPE[\s\S]*?>/gi,'')
    .replace(/<!--[\s\S]*?-->/g,'')
    .replace(/<script\b[\s\S]*?<\/script>/gi,'')
    .replace(/@import[^;]*;?/gi,'')
    .replace(/<foreignObject\b[\s\S]*?<\/foreignObject>/gi,'')
    .replace(/<iframe\b[\s\S]*?<\/iframe>/gi,'')
    .replace(/<text\b[\s\S]*?<\/text>/gi,'')
    .replace(/<(animate\w*|set)\b[^>]*\/>/gi,'')
    .replace(/<(animate\w*|set)\b[\s\S]*?<\/\1>/gi,'')
    .replace(/<a\b[^>]*>([\s\S]*?)<\/a>/gi,'$1')
    .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,'')
    .replace(/\s(?:href|xlink:href)\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,'')
    .replace(/javascript\s*:/gi,'')
    .replace(/url\(\s*["']?\s*(?!#)[^)]*\)/gi,'none')
    .trim();

  // Drop any element outside the allowlist (children are kept, the tag itself is removed).
  svg=svg.replace(/<\/?\s*([A-Za-z][\w:.-]*)\b[^>]*?\/?>/g,(tag,name)=>ALLOWED.has(name.toLowerCase())?tag:'');

  // Normalize the canvas so the site always receives a predictable 16:9 asset.
  if(/viewBox\s*=\s*["'][^"']+["']/i.test(svg)){
    svg=svg.replace(/viewBox\s*=\s*["'][^"']+["']/i,'viewBox="0 0 1200 675"');
  }else{
    svg=svg.replace(/<svg\b/i,'<svg viewBox="0 0 1200 675"');
  }
  svg=svg.replace(/(<svg\b[^>]*?)\swidth\s*=\s*["'][^"']+["']/i,'$1').replace(/(<svg\b[^>]*?)\sheight\s*=\s*["'][^"']+["']/i,'$1');
  // Browsers only render an SVG loaded via <img> when it declares the SVG namespace.
  if(!/<svg\b[^>]*\sxmlns\s*=\s*["']http:\/\/www\.w3\.org\/2000\/svg["']/i.test(svg)){
    svg=svg.replace(/<svg\b/i,'<svg xmlns="http://www.w3.org/2000/svg"');
  }

  for(const re of FORBIDDEN) if(re.test(svg)) throw new Error('SVG failed safety check: '+re);
  if(!/<(path|rect|circle|ellipse|polygon|polyline|line)\b/i.test(svg)) throw new Error('SVG has no drawable shapes after sanitizing');
  if(svg.length<350) throw new Error('SVG too small after sanitizing');
  const styleIssues=styleProblems(svg);
  if(styleIssues.length) throw new Error('SVG failed Nuvellum style gate: '+styleIssues.join('; '));

  const imagePath=`/generated/ai/${article.slug}.svg`;
  const imageAlt=`AI-generated editorial illustration for ${article.title}`.replace(/[<>]/g,'').slice(0,220);
  let markdown=String(article.markdown||'');
  markdown=setFrontmatter(markdown,'image',JSON.stringify(imagePath));
  markdown=setFrontmatter(markdown,'imageAlt',JSON.stringify(imageAlt));

  result={
    ...article,
    markdown,
    image:imagePath,
    imageAlt,
    aiImageReady:true,
    aiSvgBase64:Buffer.from(svg,'utf8').toString('base64'),
    aiSvgBytes:svg.length,
    imageGenerationMode:'gemini-svg'
  };
}catch(e){
  result={...result,aiImageError:e.message};
}
return {json:result};

