if(!has('editorialReview','passed')) problems.push('editorialReview is not "passed"');
if(!has('status','published')) problems.push('status is not "published"');
// Geography gate: explicit arrays ([] allowed), canonical region slugs and World Explorer country names only.
const allowedRegions=new Set(['north-america','latin-america-caribbean','europe-central-asia','middle-east-north-africa','sub-saharan-africa','south-asia','east-asia','southeast-asia-oceania']);
if(!Array.isArray(article.regions)) problems.push('regions is not an array');
else {
  if(article.regions.length>4||article.regions.some(x=>!allowedRegions.has(String(x)))||new Set(article.regions).size!==article.regions.length) problems.push('regions metadata is invalid');
  if(!has('regions',article.regions)) problems.push('regions frontmatter does not match article metadata');
}
if(!Array.isArray(article.countries)) problems.push('countries is not an array');
else {
  if(article.countries.length>12||new Set(article.countries).size!==article.countries.length) problems.push('countries metadata is invalid');
  const unplaced=article.countries.filter(x=>!COUNTRY_NAMES.has(String(x)));
  if(unplaced.length) problems.push('countries World Explorer cannot place: '+unplaced.join(', '));
  if(!has('countries',article.countries)) problems.push('countries frontmatter does not match article metadata');
}
if(article.risk==='sensitive'){
  if(!has('verification','cleared')) problems.push('sensitive story without verification: "cleared"');
  if(!has('reviewedBy','Nuvellum Verification Pipeline')) problems.push('sensitive story without pipeline reviewedBy');
}
if(/Prepared from (Source|Unknown|undefined) reporting/i.test(fm)) problems.push('placeholder sourceNote');
if(!/^sourceUrls: \["https:\/\/[^"]+"\]$/m.test(fm)) problems.push('sourceUrls is not a single https URL');
if(/[?&](utm_|fbclid|gclid|__source)/i.test(fm)) problems.push('tracking parameters in sourceUrls');
if(article.aiImageReady && !has('image','/generated/ai/'+article.slug+'.svg')) problems.push('image metadata does not match committed SVG');
if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(String(article.slug||''))) problems.push('invalid slug');
if(problems.length) throw new Error('Refusing to commit '+article.slug+': '+problems.join('; '));

const sourceKey=dedupeKey(article.sourceLink);
const hash=sourceHash(article.sourceLink);
// One branch per source: incoming/<slug up to 60 chars>-<8-hex source hash>.
const branchName=`incoming/${String(article.slug).slice(0,60).replace(/-+$/,'')}-${hash}`;
const contentBase64=Buffer.from(article.markdown,'utf8').toString('base64');
return {json:{...article,baseSha,sourceKey,sourceHash:hash,branchName,contentBase64}};

// n8n's Code sandbox does not expose the URL global, so source URLs are parsed by hand.
function parseSourceUrl(value) {
  const match = String(value || '').trim().match(/^(https?):\/\/([^\/?#\s]+)(\/[^?#\s]*)?(\?[^#\s]*)?(#[^\s]*)?$/i);
  if (!match || match[2].includes('@')) throw new Error('Invalid public source URL');
  const parts = match[2].toLowerCase().match(/^([a-z0-9.-]+)(?::(\d+))?$/i);
  if (!parts) throw new Error('Invalid source host');
  return { protocol: match[1].toLowerCase(), hostname: parts[1], port: parts[2] || '', pathname: match[3] || '/', search: match[4] || '' };
}
// Dedupe key: matches the repository validator (query and fragment ignored entirely).
function dedupeKey(value) {
  try {
    const u = parseSourceUrl(value);
    return 'https://' + u.hostname.replace(/^www\./, '') + (u.pathname.replace(/\/+$/, '') || '/');
  } catch {
    return String(value || '').trim().replace(/[?#].*$/, '').replace(/\/+$/, '').replace(/^http:/i, 'https:').replace(/:\/\/www\./i, '://');
  }
}

const context = $('Prepare Duplicate Context').item.json;
const raw = $input.all().map(i => i.json);
const prs = raw.flatMap(x => Array.isArray(x) ? x : [x]).filter(x => x && typeof x === 'object' && x.number);

const sourceKey = dedupeKey(context.sourceLink);
let openPrDuplicate = null;
const openPrTitles = [];

for (const pr of prs) {
  const title = String(pr.title || '').replace(/^Editorial:\s*/i, '').trim();
  if (title) openPrTitles.push(title);
  const body = String(pr.body || '');
  const matches = [...body.matchAll(/\*\*Source:\*\*\s*(https?:\/\/\S+)/g)].map(m => dedupeKey(m[1]));
  const branch = String(pr.head?.ref || '');
  if (!openPrDuplicate && (matches.includes(sourceKey) || branch.endsWith('-' + context.sourceHash8))) {
    openPrDuplicate = { number: pr.number, title: pr.title || '', html_url: pr.html_url || '' };
  }
}

return [{
  json: {
    ...context,
    normalizedSourceLink: sourceKey,
    openPrExactSourceMatch: Boolean(openPrDuplicate),
    openPrDuplicate,
    openPrTitles: [...new Set(openPrTitles)].slice(0, 100),
    exactSourceMatch: context.exactSourceMatch === true || Boolean(openPrDuplicate)
  }
}];

// Telemetry for a candidate that reached GitHub. The loop discards this item, so the GitHub API response is
// replaced by whitelisted fields only (no body, headers, URLs or error text). Never throws: telemetry cannot
// change what was committed.
const IMAGE_REASONS = [[/style gate/i, 'image_rejected_style'], [/safety check/i, 'image_rejected_safety'], [/./, 'image_no_candidate']];
let a = {};
try { a = $('Build GitHub Payload').item.json || {}; } catch {}
const err = $json && typeof $json.error === 'object' ? $json.error : ($json && $json.error ? {} : null);
const httpStatus = err ? (Number(err.httpCode || err.status || err.statusCode) || null) : null;
const imageMode = a.aiImageReady === true ? 'illustration' : 'text-led';
const imageReason = a.aiImageReady === true ? 'approved'
  : (IMAGE_REASONS.find(([re]) => re.test(String(a.aiImageError || 'none'))) || [, 'image_no_candidate'])[1];
return { json: { telemetry: {
  event: err ? 'candidate_rejected' : 'candidate_published',
  stage: 'github',
  reason: err ? 'github_push_failed' : 'published',
  httpStatus,
  slug: /^[a-z0-9-]{1,120}$/.test(String(a.slug || '')) ? a.slug : null,
  section: String(a.section || '').slice(0, 40) || null,
  risk: a.risk === 'sensitive' ? 'sensitive' : 'low',
  sourceHost: String(a.sourceHost || '').replace(/[^a-z0-9.-]/gi, '').slice(0, 80) || null,
  branch: err ? 'failed' : 'created',
  commit: err ? 'skipped' : 'ok',
  image: { mode: imageMode, reason: imageReason },
  at: Date.now()
} } };

// Run telemetry: one compact, privacy-safe summary per execution, read from the item each candidate returned to
// the loop. Only fixed reason codes and whitelisted fields leave this node: never source or article text,
// prompts, model output, full URLs, headers or credentials. It runs after the loop has finished and cannot
// affect publishing; an internal error still yields a summary (reason "telemetry_error").
const now = Date.now();
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined ? fallback : v; } catch { return fallback; } };
const slugOf = s => /^[a-z0-9-]{1,120}$/.test(String(s || '')) ? String(s) : null;
const hostOf = s => String(s || '').replace(/[^a-z0-9.-]/gi, '').slice(0, 80) || null;

function draftReason(error) {
  const e = String(error || '');
  if (/^Drafter declined|^Source is |states an opinion/.test(e)) return 'draft_skip';
  if (/region|countr/i.test(e)) return 'invalid_geography';
  if (/too short/.test(e)) return 'thin_draft';
  return 'draft_invalid';
}

// Final item of one candidate -> { stage, reason }. Order follows the pipeline's own gates.
function classify(j) {
  if (j.telemetry && typeof j.telemetry === 'object') return j.telemetry;
  if (j.sourceReady === false) return { event: 'candidate_rejected', stage: 'source', reason: 'thin_source' };
  if ('isDuplicate' in j && !('draftFailed' in j)) {
    return { event: 'candidate_rejected', stage: 'dedupe', reason: j.duplicateParserError ? 'duplicate_check_failed' : 'duplicate_story' };
  }
  if (j.exactSourceMatch === true && !('draftFailed' in j)) {
    return { event: 'candidate_rejected', stage: 'dedupe', reason: 'duplicate_source', detail: j.openPrExactSourceMatch ? 'open_pr' : 'published' };
  }
  if ('sensitiveVerified' in j && j.sensitiveVerified !== true) {
    return { event: 'candidate_rejected', stage: 'verification', reason: j.sensitiveVerificationError ? 'verification_uncertain' : 'verification_failed' };
  }
  if (j.editorialApproved === false) {
    if (j.draftFailed) return { event: 'candidate_rejected', stage: 'draft', reason: draftReason(j.draftError) };
    return { event: 'candidate_rejected', stage: 'editorial_review', reason: j.reviewParserError ? 'editorial_uncertain' : 'editorial_failed' };
  }
  return { event: 'candidate_rejected', stage: 'unknown', reason: 'unclassified' };
}

let summary;
try {
  const items = $input.all().map(i => i.json || {});
  const events = items.map(j => {
    const t = classify(j);
    return {
      event: t.event, stage: t.stage, reason: t.reason,
      ...(t.detail ? { detail: t.detail } : {}),
      ...(t.httpStatus ? { httpStatus: t.httpStatus } : {}),
      slug: slugOf(t.slug ?? j.slug),
      section: String(t.section ?? j.section ?? j.sourceSectionHint ?? '').slice(0, 40) || null,
      sourceHost: hostOf(t.sourceHost ?? j.sourceHost),
      ...(t.image ? { image: t.image } : {}),
      ...(t.risk ? { risk: t.risk } : {})
    };
  });
  const count = pred => events.filter(pred).length;
  const DRAFTED = new Set(['draft', 'editorial_review', 'verification', 'github']);
  const published = events.filter(e => e.reason === 'published');
  const queuedAt = safe(() => Number($('Queue Latest Candidates').first().json._queuedAt), NaN);
  const candidates = safe(() => $('Queue Latest Candidates').all().length, items.length);
  const qs = safe(() => $('Queue Latest Candidates').first().json._queueStats, null) || {};
  const queue = Object.fromEntries(['feedItems', 'feedErrors', 'aggregatePages', 'repeats'].map(k => [k, Number.isFinite(Number(qs[k])) ? Number(qs[k]) : null]));
  const reasons = {};
  for (const e of events) if (e.event === 'candidate_rejected') reasons[e.reason] = (reasons[e.reason] || 0) + 1;
  summary = {
    event: 'run_summary',
    telemetryVersion: 1,
    runId: safe(() => String($execution.id), null),
    mode: safe(() => String($execution.mode), null),
    queue,
    candidates,
    processed: events.length,
    unaccounted: Math.max(0, candidates - events.length),
    reachedDrafting: count(e => DRAFTED.has(e.stage)),
    editorial: {
      passed: count(e => e.stage === 'verification' || e.stage === 'github'),
      failed: count(e => e.stage === 'editorial_review')
    },
    verification: {
      passed: count(e => e.stage === 'github' && e.risk === 'sensitive'),
      failed: count(e => e.stage === 'verification')
    },
    github: {
      branchCreated: count(e => e.stage === 'github' && e.reason === 'published'),
      pushFailed: count(e => e.reason === 'github_push_failed')
    },
    published: published.length,
    rejected: count(e => e.event === 'candidate_rejected'),
    reasons,
    // Real photos are chosen after this run by the repository's visual-acquire job on the incoming branch.
    imageModes: {
      photo: 0,
      illustration: published.filter(e => e.image?.mode === 'illustration').length,
      textLed: published.filter(e => e.image?.mode === 'text-led').length
    },
    durationMs: Number.isFinite(queuedAt) ? now - queuedAt : null,
    events
  };
} catch (e) {
  summary = { event: 'run_summary', telemetryVersion: 1, reason: 'telemetry_error', runId: safe(() => String($execution.id), null), errorName: String(e && e.name || 'Error').slice(0, 40) };
}
return [{ json: summary }];
